import yaml, json
d = yaml.safe_load(open('/agent/workspace/openapi/upstream/v1.yaml'))
paths = d['paths']
for p in ['/files','/files/{fileId}']:
    if p in paths:
        print('='*20, p)
        for method, op in paths[p].items():
            if method in ('post','put'):
                print(method.upper(), op.get('operationId'))
                for c in op.get('requestBody',{}).get('content',{}):
                    print('  content-type:', c)
                    sch = op['requestBody']['content'][c].get('schema',{})
                    print(json.dumps(sch, indent=2)[:1500])
